globalThis.count = 1;
function readCount() { return globalThis.count; }
const outer = () => {
  const inner = () => globalThis.count;
  return inner();
};
console.log(globalThis.count, readCount(), outer());
globalThis.count = 2;
console.log(globalThis.count, readCount(), outer());

function readAgain() { return globalThis.count; }
const again = () => (() => globalThis.count)();
console.log(globalThis.count, readAgain(), again(), [1].map(() => globalThis.count));
